const e=JSON.parse('{"workId":"wenzi","chapter":{"id":"wenzi_ch-4","workId":"wenzi","order":4,"title":"符言","difficulty":2,"estimatedMinutes":31,"passageIds":["wenzi_ch-4_p-1","wenzi_ch-4_p-2","wenzi_ch-4_p-3","wenzi_ch-4_p-4","wenzi_ch-4_p-5","wenzi_ch-4_p-6","wenzi_ch-4_p-7","wenzi_ch-4_p-8","wenzi_ch-4_p-9","wenzi_ch-4_p-10","wenzi_ch-4_p-11","wenzi_ch-4_p-12","wenzi_ch-4_p-13","wenzi_ch-4_p-14","wenzi_ch-4_p-15","wenzi_ch-4_p-16","wenzi_ch-4_p-17","wenzi_ch-4_p-18","wenzi_ch-4_p-19","wenzi_ch-4_p-20","wenzi_ch-4_p-21","wenzi_ch-4_p-22","wenzi_ch-4_p-23","wenzi_ch-4_p-24","wenzi_ch-4_p-25","wenzi_ch-4_p-26","wenzi_ch-4_p-27","wenzi_ch-4_p-28","wenzi_ch-4_p-29","wenzi_ch-4_p-30","wenzi_ch-4_p-31"],"tags":[]},"passages":[{"id":"wenzi_ch-4_p-1","chapterId":"wenzi_ch-4","order":1,"canonicalText":"老子曰：道至高無上，至深無下，平乎準，直乎繩，圓乎規，方乎矩，包裹天地而無表裏，洞同覆蓋而無所蕒，是故原天命，治心術，理好憎，適情性，則治道通矣。","sentenceIds":["wenzi_ch-4_p-1_s-1"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：大道至高而無頂，至深而無底；像水平儀一樣平正，像墨線一樣筆直，圓潤如規，方正如矩。它囊括天地而分不出內外表裏，廣泛覆蓋萬物而絕無偏私。因此，切實體悟大道的人，喜怒不形於色，端坐時心無雜念，安睡時不做妄夢；見到事物即能客觀命名，事情來到眼前即能順應自然進行回應。","analysis":"【主題與背景】\\\\\\\\n本段出自《文子·符言》，重複闡釋「道」的至大無外與體道者的精神心境。符言篇強調君臣名實相符、遵道秉法的治國紀律。\\\\\\\\n【詞義與名物】\\\\\\\\n規矩準繩：古代四種度量衡與繪圖工具。\\\\\\\\n洞同：融通無障礙。\\\\\\\\n無所蕒：無所偏私掩蔽。\\\\\\\\n寢而不夢：神定氣足，無雜妄之夢。\\\\\\\\n【篇章解析】\\\\\\\\n本段強調「體道」不僅是個人的內在修養，更是君主處理複雜政務時所必須具備的心理素質。唯有胸懷如宇宙般開闊無私，才能客觀應對天下之變。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-2","chapterId":"wenzi_ch-4","order":2,"canonicalText":"老子曰：欲屍名者必生事，事生則舍公而就私，倍道而任己，見譽而為善，立名而為賢，則治亂矣。故聖人不求名，不立功，修身自守，物自化焉。","sentenceIds":["wenzi_ch-4_p-2_s-1","wenzi_ch-4_p-2_s-2"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：想要佔據名位的人，必定故意生事；事情一多，便捨棄公義而趨向私利，背離大道而任憑己意。為了得到稱譽才做善事，刻意樹立形象來成為賢者，於是治理不合事理，辦事不合時機。治理不合事理，責難便多；辦事不合時機，便沒有功效。妄自行事卻想求得恰中，即使偶然成功也不足以免除責任，一旦失敗卻足以使自身滅亡。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 46 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰欲屍名者必生事事生則舍公而就私倍道而任……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「欲」、「屍」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-3","chapterId":"wenzi_ch-4","order":3,"canonicalText":"老子曰：無為名屍，無為謀府，無為事任，無為智主。藏於無形，行於無怠，不為福先，不為禍始。與道同動，與德同行，此安身之術也。","sentenceIds":["wenzi_ch-4_p-3_s-1","wenzi_ch-4_p-3_s-2","wenzi_ch-4_p-3_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：不要成為名聲的主宰，不要成為計謀的府庫，不要把萬事全攬作自己的責任，也不要自居為智慧的主人。把作用隱藏在無形之中，行動卻不懈怠；不搶在福祉之前邀功，也不成為禍患的開端。事情起於尚未顯形之時，到了不得已纔行動。想求福，先使自己沒有招禍之因；想求利，先遠離可能的傷害。因無為而安寧的人，一旦失去所以安寧的根本就會危險；因無為而治理的人，一旦失去所以治理的根本就會混亂。因此《道德經》說：不想像美玉那樣光潤可貴，寧可像石頭那樣質樸落落。皮毛花紋美麗的獸，皮必被剝；角長得漂亮的獸，身體必遭殺害；甘美的泉水容易被汲乾，筆直的樹木容易被砍伐。華麗榮耀的言語，後來常成為過失；山石中藏玉，反使山受到開採傷害。百姓的禍患，原本也常出在多言炫示。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 47 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰無為名屍無為謀府無為事任無為智主藏於無……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「無」、「為」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-4","chapterId":"wenzi_ch-4","order":4,"canonicalText":"老子曰：時之行也，動以從之，不知道者，福為禍先。天為蓋，地為軫，善用道者，終無盡窮。順時而動，因地而居，因人而使，何往不通。","sentenceIds":["wenzi_ch-4_p-4_s-1","wenzi_ch-4_p-4_s-2","wenzi_ch-4_p-4_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：時機運行時，行動應當隨順；不明白道的人，反會把福轉成禍。天像車蓋，地像車廂，善於運用道的人終究不會睏乏；地像車廂，天像車蓋，善於運用道的人終究不受傷害。若把五行分別排列、強使它們競勝，必然會有一方壓倒另一方；但在天所覆蓋的整體中，萬物無不各得其宜。所以說：知道自己有所不知，是高明；不知道卻自以為知道，是弊病。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 48 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰時之行也動以從之不知道者福為禍先天……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-4_p-4）。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-5","chapterId":"wenzi_ch-4","order":5,"canonicalText":"老子曰：山生金，石生玉，反相剝；木生蟲，還自食；人生事，還自賊。夫好事者未嘗不中傷，好利者未嘗不破亡，是以聖人無事而天下治。","sentenceIds":["wenzi_ch-4_p-5_s-1","wenzi_ch-4_p-5_s-2","wenzi_ch-4_p-5_s-3","wenzi_ch-4_p-5_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：山中生金，山反因採金而被剝鑿；石中生玉，石也因取玉而受破壞。樹木生蟲，蟲回頭蛀食樹木；人生出事端，事情又反過來傷害自身。喜歡多事的人未必不一時得中，爭利的人卻終究走向困窮；善於游泳的人可能溺水，善於騎馬的人可能墜馬，各人都可能因所擅長、所愛好之事反遭禍患。獲得在於時機，不在爭奪；治理在於合道，不在迷信聖者個人。土地居下而不與人爭高，所以安穩而不危險；水向下流而不爭速度，所以前行並不遲滯。因此聖人不執著，所以沒有失落；不妄為，所以沒有失敗。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 49 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰山生金石生玉反相剝木生蟲還自食人生事還……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「山」、「生」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-6","chapterId":"wenzi_ch-4","order":6,"canonicalText":"老子曰：一言不可窮也，二言天下宗也，三言諸侯雄也，四言天下雙也。貞信則不可窮，道德則天下宗，任賢則諸侯雄，得民則天下雙。","sentenceIds":["wenzi_ch-4_p-6_s-1","wenzi_ch-4_p-6_s-2"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：有一言能使事業無窮無盡，有二言能成為天下人尊崇的宗主，有三言機能使諸侯稱雄，有四言能使天下無雙。堅持貞潔誠信則事業無窮；遵行道德則為天下所尊奉；選拔賢良有德者則可在諸侯中稱雄；厭惡奸邪少德者而博愛大眾，則能天下無雙。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 50 節。屬於古代傳統經典之精華篇章，記述先賢關於立德立言、治國用兵與天地自然哲理之重大名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰：一言不可窮也，二言天下宗也，……」之思想精華與章法結構。\\\\n2. 訓詁與語法考釋：本段重點解讀「老」、「子」等字詞之古代漢語語意、通假字與名物制度規範。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\\\\n考釋特別補充：本段體現了傳統文化博大精深之學術源流與治國安邦哲理。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-7","chapterId":"wenzi_ch-4","order":7,"canonicalText":"老子曰：人有三死，非命亡焉：飲食不節，簡賤其身，病共殺之；樂得無已，好求不止，刑共殺之；以少犯眾，弱而侮強，兵共殺之。此三者，皆自取之也。","sentenceIds":["wenzi_ch-4_p-7_s-1","wenzi_ch-4_p-7_s-2","wenzi_ch-4_p-7_s-3","wenzi_ch-4_p-7_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：人有三種死亡，不是自然壽命終了。飲食沒有節制，輕忽糟蹋自己的身體，各種疾病便共同害死他；貪求獲得沒有止境，嗜好追逐不肯停止，各種刑罰便共同害死他；以少數冒犯多數，以弱小欺凌強大，各種兵禍便共同害死他。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 51 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰人有三死非命亡焉飲食不節簡賤其身病共殺……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「人」、「有」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-8","chapterId":"wenzi_ch-4","order":8,"canonicalText":"老子曰：其施厚者其報美，其怨大者其禍深。薄施而厚望，畜怨而無患者，未之有也。察其所種，知其所獲，因果之理，昭然不爽。","sentenceIds":["wenzi_ch-4_p-8_s-1","wenzi_ch-4_p-8_s-2","wenzi_ch-4_p-8_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：給予豐厚的人，得到的回報也美好；結下的怨恨愈大，招致的禍患也愈深。施予很少卻期待厚報，積蓄怨恨卻希望沒有禍患，從來沒有這種事。考察一個人如何對待外界、送出什麼，便能知道將有什麼回到他身上。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 52 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰其施厚者其報美其怨大者其禍深薄施而厚望……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「施」、「厚」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-9","chapterId":"wenzi_ch-4","order":9,"canonicalText":"老子曰：原天命，治心術，理好憎，適情性，則治道通矣。原天命則不惑禍福，治心術則不妄喜怒，理好憎則不偏聽，適情性則不勞神，是以無往而不治。","sentenceIds":["wenzi_ch-4_p-9_s-1","wenzi_ch-4_p-9_s-2"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：探究天命，治理心術，調理好惡，使情性安適，治道便通達了。探究天命，就不被禍福迷惑；治理心術，就不任意喜怒；調理好惡，就不貪求無用之物；使情性安適，欲望便不超過節度。不被禍福迷惑，動靜便能順宜；不任意喜怒，賞罰便不偏私；不貪無用之物，就不會以欲望傷害本性；欲望不過節，便能知足養生。這四件事都不必向外尋求，也不必藉助別人，只要反求自己便能得到。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 53 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰原天命治心術理好憎適情性則治道通矣原天……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「原」、「天」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-10","chapterId":"wenzi_ch-4","order":10,"canonicalText":"老子曰：不求可非之行，不憎人之非己；修足譽之德，不求人之譽己。信己之善，不移於世俗；處己之中，不奪於利慾。此君子之所以特立獨行也。","sentenceIds":["wenzi_ch-4_p-10_s-1","wenzi_ch-4_p-10_s-2","wenzi_ch-4_p-10_s-3","wenzi_ch-4_p-10_s-4","wenzi_ch-4_p-10_s-5"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：不要故意做足以受人非議的行為，也不要憎恨別人批評自己；只管修養足以受稱譽的德行，不必要求別人稱譽自己。不能使災禍一定不來，便承認自己的智慧有限；不能使福祉一定來臨，便確信自己不應爭奪強求。若禍患到來不是自己造成的，即使困厄也不憂懼；若福運來臨不是自己成就的，即使通達也不自誇。因此能閒居而內心自樂，不妄作而自然有治。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 54 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰不求可非之行不憎人之非己修足譽之德不求……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「不」、「求」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-11","chapterId":"wenzi_ch-4","order":11,"canonicalText":"老子曰：道者，守其所已有，不求其所未得。求其所未得，則所有者亡；修其所已有，則所欲者至。貪多者必失其本，知足者長保其富。","sentenceIds":["wenzi_ch-4_p-11_s-1","wenzi_ch-4_p-11_s-2","wenzi_ch-4_p-11_s-3","wenzi_ch-4_p-11_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：合道的人守住所已有的根本，不一味追求尚未擁有的東西。只追逐未得之物，原有的也可能喪失；修養已有的根本，所希望的反會到來。局勢尚未穩固到不會混亂，就急著以多事求治，必有危險；行為尚不能免於過失，就急著求名，必受挫折。所以最大的福是不遭禍，最大的利是不喪失。因此說：事物有時想增加它，反而造成減損；想減損它，反而有所增加。道不能用來鼓勵人趨逐利益，卻可以安定精神、避免傷害；寧可常保無禍，不必追逐奇福；寧可常保無罪，不必追逐顯功。道幽遠昏微，順從天道的威儀，與天同氣而不先存思慮，不預設積蓄；來者不刻意迎取，去者不追送挽留。人事雖向東西南北變動，自身仍獨立守住中央。因此身處眾多彎曲之中，不失自己的正直；與天下一同流行而不離自身界域。不刻意標榜善，也不刻意躲避惡名；遵循天道，不搶先發端，不專任己意；循守天理，不預先算計，也不錯失時機，與天時相約。不強求獲得，也不推辭自然來到的福，遵從天道法則。內無意外的奇福，外無突來的奇禍，禍福便不以反常方式產生，又哪會有人為傷害？所以最高的德，使言論趨於共同準則，使行事共享福祉，上下一心，不生歧路旁見；使邪惡退隱，使向善道路開通，人民便有正確方向。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 55 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰道者守其所已有不求其所未得求其所未得則……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「道」、「守」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-12","chapterId":"wenzi_ch-4","order":12,"canonicalText":"老子曰：為善則勸，為不善則觀。勸則生責，觀則生患。故道不可以進而求名，可以退而修身；不可以耀而示人，可以晦而自藏。","sentenceIds":["wenzi_ch-4_p-12_s-1","wenzi_ch-4_p-12_s-2","wenzi_ch-4_p-12_s-3","wenzi_ch-4_p-12_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：做善事如果流於刻意鼓勵，做惡事如果流於刻意防範，鼓勵就會招致苛責，防範就會衍生後患。因此大道不能用來主動進取爭奪名聲，卻可以用來退隱修養自身。聖人不靠舉動追求名聲，不靠聰明才智博取聲譽，治國完全隨順自然，自己不加幹預。刻意逞強者必然失敗，強求者必然一無所得。人的智巧有窮盡之時，而天道的運轉卻暢通無阻。有智謀而不妄為，與無智者發揮同等功效；有才能而不幹擾事務，與無能者具備同等德行。表面有智若無智，有能若無能，天理通達之日，即是人為巧詐熄滅之時。人為聲名與自然天道無法同時顯耀，人若追求名聲就不會奉行天道；天道盛行時名聲之念自然止息，天道衰息而名聲張揚之日，便是國家陷入危亡之時。","analysis":"【主題與背景】\\\\\\\\n本段出自《文子·符言》，深入探討政治哲學中的「無為」與自然秩序。警惕君主切勿濫用巧智與獎懲機制，否則適得其反。\\\\\\\\n【詞義與名物】\\\\\\\\n生責：生出指摘與苛求。\\\\\\\\n生患：衍生隱患與奸詐。\\\\\\\\n道理達而人才滅：天道至理暢達時，人為巧詐之「才」便自然消退。\\\\\\\\n【篇章解析】\\\\\\\\n本段構建了道家無為而治的辯證體系。指出過度的政策幹預與功利導向會破壞社會的自然生態，唯有讓社會恢復自主秩序，才能達到真正長治久安。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-13","chapterId":"wenzi_ch-4","order":13,"canonicalText":"老子曰：使信士分財，不如定分而探籌。何則？有心者之於平，不如無心者。使廉士守財，不如封局而結緘。是故任人者不如任法，任智者不如任數。","sentenceIds":["wenzi_ch-4_p-13_s-1","wenzi_ch-4_p-13_s-2","wenzi_ch-4_p-13_s-3","wenzi_ch-4_p-13_s-4","wenzi_ch-4_p-13_s-5"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：讓全天下最講誠信的人來主持分派財產，還不如預先確定份額標準然後讓大家隨機抽取籌簽（探籌）。為什麼呢？因為縱然有最善良主觀意圖的人在追求公平，也比不上客觀無私無心的隨機規則！讓全天下最清正廉潔的人來保管財物，還不如用封條密封、加鎖結繩以防私啟。所以依賴個別人的道德人治，遠不如依賴客觀健全的法律制度；依賴個人的主觀聰明才智，遠不如依賴標準化、可檢驗的客觀制度數據（任數）！","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 57 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰使信士分財不如定分而探籌何則有心者……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-4_p-13）。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-14","chapterId":"wenzi_ch-4","order":14,"canonicalText":"老子曰：凡事人者，非以寶幣，必以卑辭。幣殫而欲不厭，卑體免辭，論說而交不結，約束而盟不固。夫以財交者，財竭而交疏；以利合者，利盡而人散。唯道德之交，乃能久長。","sentenceIds":["wenzi_ch-4_p-14_s-1","wenzi_ch-4_p-14_s-2","wenzi_ch-4_p-14_s-3","wenzi_ch-4_p-14_s-4","wenzi_ch-4_p-14_s-5"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：凡侍奉別人，不是贈送寶物財幣，就是使用謙卑言辭。但財物終會用盡，欲望卻不會滿足；屈身卑辭可以暫免責難，彼此論說交往，關係仍未必牢固；即使訂立約束、誓言盟約，約定後仍可能比預定日期更早背叛。因此君子不在外表粉飾仁義，而在內部修明治道。把境內政事修好，充分運用本地條件，勉勵人民決心守衛，鞏固城郭，使上下一心，共同守護社稷。如此，即使為了名飾而出兵的人，也不會攻伐無罪之國；為利益而來的人，也不會攻打難以攻取之國。這是保全國家的道路，也是取得實利的道理。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 58 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰凡事人者非以寶幣必以卑辭幣殫而欲不厭卑……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「凡」、「事」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-15","chapterId":"wenzi_ch-4","order":15,"canonicalText":"老子曰：聖人不勝其心，眾人不勝其欲。君子行正氣，小人行邪氣。內便於性，外合於義，動靜以天，此聖人之行也。徇欲而背理，棄義而就利，此小人之道也。","sentenceIds":["wenzi_ch-4_p-15_s-1","wenzi_ch-4_p-15_s-2","wenzi_ch-4_p-15_s-3","wenzi_ch-4_p-15_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：聖人不讓自己的本心受到壓制，眾人卻不能克服欲望；君子運行正氣，小人運行邪氣。內在使本性安適，外在符合義理，循著道理而行動，不受外物束縛，這就是正氣；一味追逐美味，沉溺聲色，隨喜怒發作而不顧後患，這就是邪氣。邪與正互相傷害，欲望與本性互相妨害，兩者不能同時成立：一方興起，另一方便衰廢，所以聖人捨棄過度欲望而順從本性。眼睛喜愛美色，耳朵喜愛聲音，鼻子喜愛香氣，嘴巴喜愛滋味；把這些合在一起而產生快感，又總牽涉利害，便形成嗜慾。其實耳目鼻口本身不知道要追求什麼，都是心在支配它們；若心使各種感官各得適當位置，由此也就可以明白，欲望並非不可克服。","analysis":"【主旨】本段把欲望問題的主導權放在心：感官只是接受聲色香味，是否沉溺以及能否節制，取決於心如何組織、評價這些感受。\\\\n【關鍵詞義】「不勝其心」依正邪、性慾的對舉，指不使本心受壓倒；「推於滋味」是向滋味追逐擴張；「各得其所」是各種感官活動各有適當限度。\\\\n【章法與思想】先列聖人、眾人和正邪之別，再界定正氣、邪氣，最後拆解嗜慾的形成。結句「欲不可勝」按上下文應理解為「說欲望不能克服」的觀點不成立，而非主張欲望必然無敵。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-16","chapterId":"wenzi_ch-4","order":16,"canonicalText":"老子曰：治身養性者，節寢處，適飲食，和喜怒，便動靜。內在己者得，而邪氣無由入。飾外者傷內，徇名者喪真，去華取實，身安而神全。","sentenceIds":["wenzi_ch-4_p-16_s-1","wenzi_ch-4_p-16_s-2","wenzi_ch-4_p-16_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：治理身體、涵養本性的人，調節睡眠起居，使飲食適宜，調和喜怒，使動靜便利合度。內在屬於自己的部分得到安頓，邪氣便無從侵入。裝飾外表，往往傷害內部；放縱情慾，會損害精神；只看外在文采，會遮蔽真實。片刻都不忘扮演賢者，必定困苦本性；走一百步都不肯忘記維持儀容，必定拖累身體。因此羽翼過分華美，可能傷及骨骸；枝葉過度茂盛，可能損害根荄。內外兩面都追求極致華美，天下沒有能長久做到的。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 60 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰治身養性者節寢處適飲食和喜怒便動靜內在……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「治」、「身」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-17","chapterId":"wenzi_ch-4","order":17,"canonicalText":"老子曰：天有明，不憂民之晦也；地有財，不憂民之貧也。至德之道者，若丘山，嵬然不動，行者以為期，居者以為安。大公無私，百姓自然富庶。","sentenceIds":["wenzi_ch-4_p-17_s-1","wenzi_ch-4_p-17_s-2","wenzi_ch-4_p-17_s-3","wenzi_ch-4_p-17_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：天擁有光明，卻不為人民的昏暗憂慮；地擁有財富，卻不為人民的貧乏焦慮。具有至德與道的人像山丘大山，巍然不動，行路者自然把它當作方向標準。他只端正自己而使萬物充足，不把這當成對人的賞賜；使用其成果的人，也不必承受報德壓力，所以安定而能長久。天地不以私意給予，所以也不奪取；不自居有德，所以不招怨。動輒發怒的人必多結怨，喜歡以恩惠給人的人也常會強行取回；只有隨順天地自然，才能合乎事理。因此稱譽一旦顯露，毀謗便隨之而來；善名一旦顯露，惡名便跟著出現。利益可能成為傷害的開端，福分可能成為災禍的先聲。不強求利益，便少受其害；不強求福分，便少招其禍。生命以保全為常道，富貴只是暫時寄寓。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 61 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰天有明不憂民之晦也地有財不憂民之貧也至……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「天」、「有」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-18","chapterId":"wenzi_ch-4","order":18,"canonicalText":"老子曰：聖人無屈奇之服，詭異之行。服不雜，行不觀，通而不華，窮而不懾，榮而不顯，辱而不慼。澹然無欲，不隨物轉，此德之盛也。","sentenceIds":["wenzi_ch-4_p-18_s-1","wenzi_ch-4_p-18_s-2","wenzi_ch-4_p-18_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：聖人不穿曲折奇異的服裝，不做詭怪異常的行為；衣著不雜亂，行動不刻意供人觀賞。處境通達而不浮華，處境困窮而不恐懼；榮顯而不炫耀，隱沒而不自辱；與人不同卻不故作怪異，與人相同地做事也無法用固定名目限定他。這叫作大通。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 62 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰聖人無屈奇之服詭異之行服不雜行不觀通而……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「聖」、「人」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-19","chapterId":"wenzi_ch-4","order":19,"canonicalText":"老子曰：道者，直己而待命。時之至，不可迎而反也；時之去，不可足而援也。故聖人不進而求，不退而怨，順時隨變，與化俱遊。","sentenceIds":["wenzi_ch-4_p-19_s-1","wenzi_ch-4_p-19_s-2","wenzi_ch-4_p-19_s-3","wenzi_ch-4_p-19_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：合道的人先端正自己，等待天命時機。時機來到，不能預先迎取而迫使它折返；時機離去，也不能追趕攀援使它停留。所以聖人不向前強求，也不向後矯讓。隨順時機若久，時勢離去時我便跟著走；離開時勢若久，時勢也可能轉到我身後。無所謂刻意離開或趨就，只在自己的位置保持中正。天道沒有偏親，只幫助有德者。福分到來不是自己強求所得，所以不誇耀功勞；禍患到來若不是自己造成，也不後悔正當行為。內心恬靜，不使外物牽累德性；即使狗突然吠叫也不驚慌，因為確信自己的真情，確實沒有越出本分。所以通達道的人不迷惑，知道命限的人不憂愁。帝王死後，形骸埋藏在野外，祭祀時精神牌位卻奉於明堂，這表示精神比形體受到重視。因此精神主宰形體，形體便順從；形體欲望勝過精神，人便困窮。耳目聰明雖可使用，仍須返回由精神統攝，這叫大通。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 63 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰道者直己而待命時之至不可迎而反也時之去……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「道」、「直」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-20","chapterId":"wenzi_ch-4","order":20,"canonicalText":"老子曰：古之存己者，樂德而忘賤，故名不動志；樂道而忘貧，故利不動心。是以謙而能樂，卑而能安，富貴不能淫，貧賤不能移。","sentenceIds":["wenzi_ch-4_p-20_s-1","wenzi_ch-4_p-20_s-2","wenzi_ch-4_p-20_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：古代善於保存自身的人，以德為樂，因而忘記地位卑賤，所以名聲不能動搖志向；以道為樂，因而忘記生活貧困，所以利益不能動搖內心。因此他們謙下而能喜樂，安靜而能恬淡。用只有短短可數年限的人生去憂愁天下的混亂，就像擔心河水乾涸，想靠自己的眼淚替它增水一樣。所以不徒然憂愁天下之亂，轉而以修治自身為樂的人，才可以和他談論道。","analysis":"【主旨】本段不是鼓勵對亂世冷漠，而是批評個人把無限天下之憂全壓在有限生命上；實際起點應是先使自身不受名利擾亂。\\\\n【關鍵詞義】「存己」是保全、安頓自身；「數筭之壽」指年數有限、可以計算的生命；「泣而益之」以眼淚補河水，比喻力量與目標極不相稱。\\\\n【章法與思想】先以樂德、樂道對治賤與貧，再用補河的誇張譬喻說明空憂無益，最後落到「身治」。重點是把憂世轉化為可實踐的修身，不是取消公共責任。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-21","chapterId":"wenzi_ch-4","order":21,"canonicalText":"老子曰：人有三怨：爵高者人妒之，官大者主惡之，祿厚者人怨之。夫爵益高者意益下，官益大者心益小，祿益厚者施益博。如此，則可以免於三怨矣。","sentenceIds":["wenzi_ch-4_p-21_s-1","wenzi_ch-4_p-21_s-2","wenzi_ch-4_p-21_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：人有三種常面臨的怨恨嫉妒：爵位高的人別人會嫉妒他，官職大的人君主會厭惡忌憚他，俸祿厚的人大眾會怨恨他。因此，爵位越高者態度要越發謙卑，官職越大者心思要越發謹慎細小，俸祿越厚者施捨要越發廣博。修持好這三點，怨恨就不會產生。所以說，尊貴是以卑賤為根本，高大是以低下為基礎。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 65 節。屬於古代傳統經典之精華篇章，記述先賢關於立德立言、治國用兵與天地自然哲理之重大名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰：人有三怨：爵高者人妒之，官大……」之思想精華與章法結構。\\\\n2. 訓詁與語法考釋：本段重點解讀「老」、「子」等字詞之古代漢語語意、通假字與名物制度規範。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\\\\n考釋特別補充：本段體現了傳統文化博大精深之學術源流與治國安邦哲理。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-22","chapterId":"wenzi_ch-4","order":22,"canonicalText":"老子曰：言者所以通己於人也，聞者所以通人於己也。既聞其聾，人道不通，故有聞聾之病。聖人兼聽廣納，無私蔽，無耳目之塞，故天下治。","sentenceIds":["wenzi_ch-4_p-22_s-1","wenzi_ch-4_p-22_s-2","wenzi_ch-4_p-22_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：言語是用來使自己與別人相通的，聽聞是用來了解他人的。傳文本段開頭通人於所既聞其聾等字句不穩，但下文大意是：人的溝通若閉塞，便會患上如同聽覺失靈的毛病，不能明白事理如何通達。難道只有形體才會昏暗耳聾嗎？心也同樣可能如此。內心閉塞，不知道通達的方向，就是精神上的昏聾。道作為萬物的根宗，一切有形之物都由它而生，它作為親本可說極其親近；凡食穀物、受氣而生者都靠它保全壽命，它作為君主可說極有恩惠；各種有智慧的人都向它學習，它作為老師可說極其明達。人常拿無用之事妨害真正有用之事，所以知識不能廣博，時間也一天比一天不足。如果能把用來博弈消遣的日子拿來問道，見聞便能加深。肯問與不肯問的差別，就像耳聰目明的人與昏聾者的差別。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 66 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰言者所以通己於人也聞者所以通人於己……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-4_p-22）。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-23","chapterId":"wenzi_ch-4","order":23,"canonicalText":"老子曰：人之情，心服於德，不服於力。德在與不在取，是以聖人之慾貴於人者，先貴於人；欲愛於人者，先愛於人。未有己不施而望於人者也。","sentenceIds":["wenzi_ch-4_p-23_s-1","wenzi_ch-4_p-23_s-2","wenzi_ch-4_p-23_s-3","wenzi_ch-4_p-23_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：依人的常情，內心會服從德行，而不會真正服從強力；能否得到人心，在於自身有沒有德。因此聖人想被別人看重，先看重別人；想受別人尊敬，先尊敬別人；想勝過別人，先戰勝自己；想使自己居於人下，便先謙卑自處。所以貴賤尊卑，都應由道來節制。古代聖王言辭謙下於人，身分位置退居人後，天下人便樂意推戴而不厭倦，擁戴他也不覺得負擔沉重；這是因為他的德厚有餘、氣順不逆。因此懂得給予就是取得、居後反能在先，便接近於道了。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 67 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰人之情心服於德不服於力德在與不在取是以……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「人」、「情」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-24","chapterId":"wenzi_ch-4","order":24,"canonicalText":"老子曰：德少而寵多者譏，才下而位高者危，無大功而有厚祿者微。故物或益之而損，或損之而益。量力而處，不過其分，則安矣。","sentenceIds":["wenzi_ch-4_p-24_s-1","wenzi_ch-4_p-24_s-2","wenzi_ch-4_p-24_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：德行少而寵愛多，會受到譏議；才能低而職位高，處境危險；沒有大功卻享有厚祿，地位也會衰微。所以事物有時看似增加它，反而造成減損；看似減損它，反而有所增益。眾人都知道把利益當作利益，卻不知道把禍患真正看成禍患；只有聖人明白，有些患難可轉成利益，有些利益反會成為禍患。因此一年兩度結果的樹木，根部必受損傷；家藏寶物而被人發掘，後代必遭災殃。巨大利益反而轉成傷害，這是天道盛極必反的規律。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 68 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰德少而寵多者譏才下而位高者危無大功而有……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「德」、「少」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-25","chapterId":"wenzi_ch-4","order":25,"canonicalText":"老子曰：小人從事曰苟得，君子曰苟義。為善者，非求名者也，而名從之；名不與利期，而利歸之。苟得者求利而得害，苟義者避名而名彰。","sentenceIds":["wenzi_ch-4_p-25_s-1","wenzi_ch-4_p-25_s-2","wenzi_ch-4_p-25_s-3","wenzi_ch-4_p-25_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：小人做事只說只要能得到就好，君子則說只要合乎義就好。行善的人，本來不是為求名聲，名聲卻隨之而來；名聲原本沒有和利益約定，利益也可能歸向他。表面上同樣有所追求，最後達到的境地卻不同。因此一項行動看似有益時，損害也可能隨在後面。說話沒有永遠固定的是、行動也不考慮隨時制宜，這是小人的層次；能明察一件事、精通一項能力，是中等之人；能普遍包容各方，又能依人的技能才具加以任用，才是聖人的層次。","analysis":"【主旨】本段以「苟得／苟義」區分行動動機，並由單項能力推到能包容、任用眾才的治理智慧。\\\\n【關鍵詞義】「苟得」是隻求取得而不問方式；「苟義」是首先要求合義；「言無常是，行無常宜」不是反對彈性，而是批評既沒有穩定原則，又不能因時合宜；「兼覆」是普遍覆育包容。\\\\n【章法與思想】先比較小人、君子的目的，再說名利可能是行善的非預期結果，接著提醒利中有害，最後排列小人、中人、聖人三個認知與用人層次。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-26","chapterId":"wenzi_ch-4","order":26,"canonicalText":"老子曰：生，所假也；死，所歸也。故世治則以義衛身，世亂則以身衛義。死之日，行之終也，故君子慎終如始，死生一如，無所愧怍。","sentenceIds":["wenzi_ch-4_p-26_s-1","wenzi_ch-4_p-26_s-2","wenzi_ch-4_p-26_s-3","wenzi_ch-4_p-26_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：生命是暫時借來的，死亡是最終歸宿。因此世道清明時，以義來保衛自身；世道混亂時，則以自身來保衛義。死亡之日是一生行為的終點，所以君子只須慎重使用這一次生命。生命受之於天，命運則是所遭遇的時勢。有才卻沒有遇到合適時代，是天時所限；追求事物有應守的方法，能否得到則在命運。君子能夠行善，卻不能保證一定得福；他不忍作惡，但也未必因此完全免禍。所以君子遇到時機便進用，以合義的方式取得，又有什麼僥倖可說？時機不合便退讓，以禮讓出位置，又有什麼不幸可說？因此即使處在貧賤仍不後悔，是因他已得到自己真正看重的義。","analysis":"【主旨】本段區分可自主的道義選擇與不可控制的時命結果：君子慎用一生，卻不把得福免禍當成行善的交換條件。\\\\n【關鍵詞義】「生所假」把生命視為暫借；「慎一用」是慎重運用僅有一次的生命；「求之有道，得之在命」指出方法屬於人，結果受時命限制。\\\\n【章法與思想】由生死定位切入，再說治世護身、亂世衛義，接著分析才、時、命，最後以進退皆合義禮消解幸與不幸。安貧不悔不是宿命消極，而是價值不交給外在結果裁定。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-27","chapterId":"wenzi_ch-4","order":27,"canonicalText":"老子曰：人有順逆之氣生於心，心治則氣順，心亂則氣逆。心之治亂在於道德，得道則心治，失道則心亂。故聖人修道德以正其心，心正而氣和，氣和而萬物應。","sentenceIds":["wenzi_ch-4_p-27_s-1","wenzi_ch-4_p-27_s-2","wenzi_ch-4_p-27_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：人有順和與逆亂之氣，都從內心產生。心安定，氣便和順；心混亂，氣便逆亂。心的治亂取決於道德：得道，心便安定；失道，心便混亂。心安定，人與人交往便互相辭讓；心混亂，便互相爭奪。辭讓形成德，爭奪滋生傷害；有德，氣便和順，傷害滋生，氣便逆亂。氣和順，就願減少自己來供給別人；氣逆亂，就損害別人來奉養自己。這兩種氣，可以藉由道來調整控制。天道好像回聲回應聲音：德行積累，福祉便產生；禍害積累，怨恨便形成。官職常敗在權勢最盛之時，孝心常在有了妻子兒女後衰退，禍患常在憂慮解除時萌生，疾病常在將要痊癒時加重。所以說：結束時和開始時一樣謹慎，就不會敗壞事情。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 71 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰人有順逆之氣生於心心治則氣順心亂則氣逆……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「人」、「有」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-28","chapterId":"wenzi_ch-4","order":28,"canonicalText":"老子曰：舉枉與直，如何不得；舉直與枉，勿與遂往。所謂同汙而異泥者，處濁世而自保其清，隨流俗而不失其真也。","sentenceIds":["wenzi_ch-4_p-28_s-1","wenzi_ch-4_p-28_s-2","wenzi_ch-4_p-28_s-3"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：若推舉邪曲者而把正直者交給他支配，怎能得到善治？若推舉正直者而讓邪曲者與他共事，也不要任由邪曲者一路牽引。這就是所謂雖同處污濁環境，卻不一同陷入泥淖。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 72 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰舉枉與直如何不得舉直與枉勿與遂往所謂同……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「舉」、「枉」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-29","chapterId":"wenzi_ch-4","order":29,"canonicalText":"老子曰：聖人同死生，愚人亦同死生。愚人不知利害之所在，無所畏懼；聖人深知天道之變化，順化安常。道懸於天，物布於地，和在於人。人主若能體道通和，則天下安矣。","sentenceIds":["wenzi_ch-4_p-29_s-1","wenzi_ch-4_p-29_s-2","wenzi_ch-4_p-29_s-3","wenzi_ch-4_p-29_s-4","wenzi_ch-4_p-29_s-5"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：聖人把生死看作一體，愚人有時也同樣不分生死；兩者差別在於能否調和利害所在。道高懸於天，萬物分佈於地，而調和的責任在人。君主若不能使人事和諧，古人認為天氣便不能下降，地氣不能上升，陰陽不能協調，風雨不能按時，人民因而生病挨餓。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 73 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰聖人同死生愚人亦同死生愚人不知利害……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-4_p-29）。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-30","chapterId":"wenzi_ch-4","order":30,"canonicalText":"老子曰：得萬人之兵，不如聞一言之當；得隋侯之珠，不如得事之所由；得和氏之璧，不如得行之所宜。至寶在道不在物，明君貴道而不貴珠玉。","sentenceIds":["wenzi_ch-4_p-30_s-1","wenzi_ch-4_p-30_s-2","wenzi_ch-4_p-30_s-3","wenzi_ch-4_p-30_s-4"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：得到萬人的軍隊，不如聽到一句切合事理的話；得到隨侯之珠，不如掌握事情發生的原因；得到和氏璧，不如明白事情應當走向何處。天下即使廣大，喜歡動用武力的也會滅亡；國家即使安定，好戰也會陷入危險。所以《道德經》說：使國家小、人民少，即使有各種器械也不輕易使用。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 74 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰得萬人之兵不如聞一言之當得隋侯之珠不如……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「得」、「萬」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"wenzi_ch-4_p-31","chapterId":"wenzi_ch-4","order":31,"canonicalText":"老子曰：能成霸王者，必勝者也；能勝敵者，必強者也；能強者，必用人力者也；能用人力者，必得人心者也；能得人心者，必自得者也。自得者，修道以正其身，天下自然歸之。","sentenceIds":["wenzi_ch-4_p-31_s-1","wenzi_ch-4_p-31_s-2","wenzi_ch-4_p-31_s-3","wenzi_ch-4_p-31_s-4","wenzi_ch-4_p-31_s-5","wenzi_ch-4_p-31_s-6"],"sourceRefs":[{"label":"《文子》—中國哲學書電子化計劃","edition":"李定生等《文子新書》本","location":"https://ctext.org/wenzi/zh","accessedAt":"2026-08-31"},{"label":"《文子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/文子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"老子說：能成就霸王之業的人，必須能取勝；能戰勝敵人的，必須強大；能強大的，必須善用眾人的力量；能運用眾人力量的，必須得到人心；能得到人心的，必須先能安頓自身；能安頓自身的，最後必定依靠柔弱之道。只勝過不如自己的人，遇到和自己相當的對手便會相格相持；以柔弱取勝，效力卻能超出與自己相當者，其作用不可估量。所以能承受許多局部的不勝，反而成就最後的大勝。","analysis":"【題解與背景】\\\\n本段選自《文子》〈符言〉第 75 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰能成霸王者必勝者也能勝敵者必強者也……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-4_p-31）。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"wenzi_ch-4_p-1_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-1","order":1,"canonicalText":"老子曰：道至高無上，至深無下，平乎準，直乎繩，圓乎規，方乎矩，包裹天地而無表裏，洞同覆蓋而無所蕒，是故原天命，治心術，理好憎，適情性，則治道通矣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-2_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-2","order":1,"canonicalText":"老子曰：欲屍名者必生事，事生則舍公而就私，倍道而任己，見譽而為善，立名而為賢，則治亂矣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-2_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-2","order":2,"canonicalText":"故聖人不求名，不立功，修身自守，物自化焉。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-3_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-3","order":1,"canonicalText":"老子曰：無為名屍，無為謀府，無為事任，無為智主。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-3_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-3","order":2,"canonicalText":"藏於無形，行於無怠，不為福先，不為禍始。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-3_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-3","order":3,"canonicalText":"與道同動，與德同行，此安身之術也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-4_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-4","order":1,"canonicalText":"老子曰：時之行也，動以從之，不知道者，福為禍先。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-4_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-4","order":2,"canonicalText":"天為蓋，地為軫，善用道者，終無盡窮。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-4_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-4","order":3,"canonicalText":"順時而動，因地而居，因人而使，何往不通。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-5_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-5","order":1,"canonicalText":"老子曰：山生金，石生玉，反相剝；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-5_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-5","order":2,"canonicalText":"木生蟲，還自食；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-5_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-5","order":3,"canonicalText":"人生事，還自賊。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-5_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-5","order":4,"canonicalText":"夫好事者未嘗不中傷，好利者未嘗不破亡，是以聖人無事而天下治。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-6_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-6","order":1,"canonicalText":"老子曰：一言不可窮也，二言天下宗也，三言諸侯雄也，四言天下雙也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-6_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-6","order":2,"canonicalText":"貞信則不可窮，道德則天下宗，任賢則諸侯雄，得民則天下雙。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-7_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-7","order":1,"canonicalText":"老子曰：人有三死，非命亡焉：飲食不節，簡賤其身，病共殺之；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-7_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-7","order":2,"canonicalText":"樂得無已，好求不止，刑共殺之；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-7_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-7","order":3,"canonicalText":"以少犯眾，弱而侮強，兵共殺之。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-7_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-7","order":4,"canonicalText":"此三者，皆自取之也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-8_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-8","order":1,"canonicalText":"老子曰：其施厚者其報美，其怨大者其禍深。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-8_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-8","order":2,"canonicalText":"薄施而厚望，畜怨而無患者，未之有也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-8_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-8","order":3,"canonicalText":"察其所種，知其所獲，因果之理，昭然不爽。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-9_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-9","order":1,"canonicalText":"老子曰：原天命，治心術，理好憎，適情性，則治道通矣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-9_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-9","order":2,"canonicalText":"原天命則不惑禍福，治心術則不妄喜怒，理好憎則不偏聽，適情性則不勞神，是以無往而不治。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-10_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-10","order":1,"canonicalText":"老子曰：不求可非之行，不憎人之非己；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-10_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-10","order":2,"canonicalText":"修足譽之德，不求人之譽己。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-10_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-10","order":3,"canonicalText":"信己之善，不移於世俗；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-10_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-10","order":4,"canonicalText":"處己之中，不奪於利慾。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-10_s-5","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-10","order":5,"canonicalText":"此君子之所以特立獨行也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-11_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-11","order":1,"canonicalText":"老子曰：道者，守其所已有，不求其所未得。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-11_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-11","order":2,"canonicalText":"求其所未得，則所有者亡；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-11_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-11","order":3,"canonicalText":"修其所已有，則所欲者至。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-11_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-11","order":4,"canonicalText":"貪多者必失其本，知足者長保其富。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-12_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-12","order":1,"canonicalText":"老子曰：為善則勸，為不善則觀。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-12_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-12","order":2,"canonicalText":"勸則生責，觀則生患。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-12_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-12","order":3,"canonicalText":"故道不可以進而求名，可以退而修身；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-12_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-12","order":4,"canonicalText":"不可以耀而示人，可以晦而自藏。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-13_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-13","order":1,"canonicalText":"老子曰：使信士分財，不如定分而探籌。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-13_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-13","order":2,"canonicalText":"何則？","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-13_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-13","order":3,"canonicalText":"有心者之於平，不如無心者。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-13_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-13","order":4,"canonicalText":"使廉士守財，不如封局而結緘。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-13_s-5","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-13","order":5,"canonicalText":"是故任人者不如任法，任智者不如任數。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-14_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-14","order":1,"canonicalText":"老子曰：凡事人者，非以寶幣，必以卑辭。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-14_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-14","order":2,"canonicalText":"幣殫而欲不厭，卑體免辭，論說而交不結，約束而盟不固。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-14_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-14","order":3,"canonicalText":"夫以財交者，財竭而交疏；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-14_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-14","order":4,"canonicalText":"以利合者，利盡而人散。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-14_s-5","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-14","order":5,"canonicalText":"唯道德之交，乃能久長。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-15_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-15","order":1,"canonicalText":"老子曰：聖人不勝其心，眾人不勝其欲。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-15_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-15","order":2,"canonicalText":"君子行正氣，小人行邪氣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-15_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-15","order":3,"canonicalText":"內便於性，外合於義，動靜以天，此聖人之行也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-15_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-15","order":4,"canonicalText":"徇欲而背理，棄義而就利，此小人之道也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-16_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-16","order":1,"canonicalText":"老子曰：治身養性者，節寢處，適飲食，和喜怒，便動靜。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-16_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-16","order":2,"canonicalText":"內在己者得，而邪氣無由入。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-16_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-16","order":3,"canonicalText":"飾外者傷內，徇名者喪真，去華取實，身安而神全。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-17_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-17","order":1,"canonicalText":"老子曰：天有明，不憂民之晦也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-17_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-17","order":2,"canonicalText":"地有財，不憂民之貧也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-17_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-17","order":3,"canonicalText":"至德之道者，若丘山，嵬然不動，行者以為期，居者以為安。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-17_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-17","order":4,"canonicalText":"大公無私，百姓自然富庶。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-18_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-18","order":1,"canonicalText":"老子曰：聖人無屈奇之服，詭異之行。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-18_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-18","order":2,"canonicalText":"服不雜，行不觀，通而不華，窮而不懾，榮而不顯，辱而不慼。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-18_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-18","order":3,"canonicalText":"澹然無欲，不隨物轉，此德之盛也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-19_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-19","order":1,"canonicalText":"老子曰：道者，直己而待命。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-19_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-19","order":2,"canonicalText":"時之至，不可迎而反也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-19_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-19","order":3,"canonicalText":"時之去，不可足而援也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-19_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-19","order":4,"canonicalText":"故聖人不進而求，不退而怨，順時隨變，與化俱遊。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-20_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-20","order":1,"canonicalText":"老子曰：古之存己者，樂德而忘賤，故名不動志；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-20_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-20","order":2,"canonicalText":"樂道而忘貧，故利不動心。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-20_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-20","order":3,"canonicalText":"是以謙而能樂，卑而能安，富貴不能淫，貧賤不能移。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-21_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-21","order":1,"canonicalText":"老子曰：人有三怨：爵高者人妒之，官大者主惡之，祿厚者人怨之。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-21_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-21","order":2,"canonicalText":"夫爵益高者意益下，官益大者心益小，祿益厚者施益博。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-21_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-21","order":3,"canonicalText":"如此，則可以免於三怨矣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-22_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-22","order":1,"canonicalText":"老子曰：言者所以通己於人也，聞者所以通人於己也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-22_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-22","order":2,"canonicalText":"既聞其聾，人道不通，故有聞聾之病。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-22_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-22","order":3,"canonicalText":"聖人兼聽廣納，無私蔽，無耳目之塞，故天下治。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-23_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-23","order":1,"canonicalText":"老子曰：人之情，心服於德，不服於力。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-23_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-23","order":2,"canonicalText":"德在與不在取，是以聖人之慾貴於人者，先貴於人；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-23_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-23","order":3,"canonicalText":"欲愛於人者，先愛於人。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-23_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-23","order":4,"canonicalText":"未有己不施而望於人者也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-24_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-24","order":1,"canonicalText":"老子曰：德少而寵多者譏，才下而位高者危，無大功而有厚祿者微。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-24_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-24","order":2,"canonicalText":"故物或益之而損，或損之而益。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-24_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-24","order":3,"canonicalText":"量力而處，不過其分，則安矣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-25_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-25","order":1,"canonicalText":"老子曰：小人從事曰苟得，君子曰苟義。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-25_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-25","order":2,"canonicalText":"為善者，非求名者也，而名從之；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-25_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-25","order":3,"canonicalText":"名不與利期，而利歸之。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-25_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-25","order":4,"canonicalText":"苟得者求利而得害，苟義者避名而名彰。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-26_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-26","order":1,"canonicalText":"老子曰：生，所假也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-26_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-26","order":2,"canonicalText":"死，所歸也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-26_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-26","order":3,"canonicalText":"故世治則以義衛身，世亂則以身衛義。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-26_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-26","order":4,"canonicalText":"死之日，行之終也，故君子慎終如始，死生一如，無所愧怍。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-27_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-27","order":1,"canonicalText":"老子曰：人有順逆之氣生於心，心治則氣順，心亂則氣逆。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-27_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-27","order":2,"canonicalText":"心之治亂在於道德，得道則心治，失道則心亂。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-27_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-27","order":3,"canonicalText":"故聖人修道德以正其心，心正而氣和，氣和而萬物應。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-28_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-28","order":1,"canonicalText":"老子曰：舉枉與直，如何不得；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-28_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-28","order":2,"canonicalText":"舉直與枉，勿與遂往。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-28_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-28","order":3,"canonicalText":"所謂同汙而異泥者，處濁世而自保其清，隨流俗而不失其真也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-29_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-29","order":1,"canonicalText":"老子曰：聖人同死生，愚人亦同死生。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-29_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-29","order":2,"canonicalText":"愚人不知利害之所在，無所畏懼；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-29_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-29","order":3,"canonicalText":"聖人深知天道之變化，順化安常。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-29_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-29","order":4,"canonicalText":"道懸於天，物布於地，和在於人。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-29_s-5","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-29","order":5,"canonicalText":"人主若能體道通和，則天下安矣。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-30_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-30","order":1,"canonicalText":"老子曰：得萬人之兵，不如聞一言之當；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-30_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-30","order":2,"canonicalText":"得隋侯之珠，不如得事之所由；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-30_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-30","order":3,"canonicalText":"得和氏之璧，不如得行之所宜。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-30_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-30","order":4,"canonicalText":"至寶在道不在物，明君貴道而不貴珠玉。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-31_s-1","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-31","order":1,"canonicalText":"老子曰：能成霸王者，必勝者也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-31_s-2","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-31","order":2,"canonicalText":"能勝敵者，必強者也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-31_s-3","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-31","order":3,"canonicalText":"能強者，必用人力者也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-31_s-4","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-31","order":4,"canonicalText":"能用人力者，必得人心者也；","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-31_s-5","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-31","order":5,"canonicalText":"能得人心者，必自得者也。","chunks":[],"tags":[]},{"id":"wenzi_ch-4_p-31_s-6","workId":"wenzi","chapterId":"wenzi_ch-4","passageId":"wenzi_ch-4_p-31","order":6,"canonicalText":"自得者，修道以正其身，天下自然歸之。","chunks":[],"tags":[]}]}');export{e as default};
